  assert.deepEqual(env, { DB_PASS: '1234', NOME: 'estudo' });
});

test('lança erro quando a linha não tem o sinal de igual', () => {
  assert.throws(() => variaveisDeAmbiente('SEM_IGUAL'), /CHAVE=valor/);
