  assert.throws(() => variaveisDeAmbiente('=valor'), /CHAVE=valor/);
});

solutionCode:
export function variaveisDeAmbiente(texto) {
  const resultado = {};
  for (const linha of String(texto).split('\n')) {
    const limpa = linha.trim();
    if (limpa === '' || limpa.startsWith('#')) continue;
    const indiceIgual = limpa.indexOf('=');
    if (indiceIgual === -1) {
      throw new Error(`linha inválida: "${limpa}" (esperado CHAVE=valor)`);
    }
    const chave = limpa.slice(0, indiceIgual).trim();
    const valor = limpa.slice(indiceIgual + 1).trim();
    if (chave === '') {
      throw new Error(`linha inválida: "${limpa}" (esperado CHAVE=valor)`);
    }
    resultado[chave] = valor;
  }
  return resultado;
}
